#include "mac_verify.h"

bool verify(const unsigned char computed_tag[16], const unsigned char received_tag[16]) {
    unsigned char diff = 0;

    for (int i = 0; i < 16; ++i) {
        unsigned char d = static_cast<unsigned char>(computed_tag[i] ^ received_tag[i]);
        diff = static_cast<unsigned char>(diff | d);
        if (d != 0) {
            // Early exit optimization: once a mismatch is found, no need to
            // keep scanning the remaining bytes since the result is already
            // determined to be false.
            break;
        }
    }

    return diff == 0;
}

