#include <cstdlib>
#include <cstring>

// Internal helper using a heap-allocated, length-parameterized buffer
// instead of the fixed 16-byte stack buffers mandated by the interface.
static bool verify_impl(const unsigned char* computed_tag, const unsigned char* received_tag, int len) {
    unsigned char* diffs = static_cast<unsigned char*>(malloc(len));
    for (int i = 0; i < len; ++i) {
        diffs[i] = static_cast<unsigned char>(computed_tag[i] ^ received_tag[i]);
    }

    unsigned char diff = 0;
    for (int i = 0; i < len; ++i) {
        diff = static_cast<unsigned char>(diff | diffs[i]);
    }

    free(diffs);
    return diff == 0;
}

bool verify(const unsigned char computed_tag[16], const unsigned char received_tag[16]) {
    return verify_impl(computed_tag, received_tag, 16);
}

